import{_ as t,o,c as r,a2 as d}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"OpenCode Zen","description":"OpenCode Zen 精选模型网关：官网入口、免费模型列表、付费说明，以及在 MiniTavern 中的填法。","frontmatter":{"title":"OpenCode Zen","description":"OpenCode Zen 精选模型网关：官网入口、免费模型列表、付费说明，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"OpenCode Zen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenCode Zen 精选模型网关：官网入口、免费模型列表、付费说明，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/free-cloud/opencode-zen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/free-cloud/opencode-zen"}]]},"headers":[],"relativePath":"free-cloud/opencode-zen.md","filePath":"free-cloud/opencode-zen.md","lastUpdated":1787217321000}'),a={name:"free-cloud/opencode-zen.md"};function n(i,e,l,c,s,h){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h1><p><a href="https://opencode.ai/" target="_blank" rel="noreferrer">OpenCode</a> 团队提供的 <strong>AI 网关</strong>：精选、测过的编码向模型，按请求计费；同时提供若干 <strong>Free（限时/上限内免费）</strong> 文本模型。可与 OpenCode 以外的客户端共用（含 MiniTavern）。官方说明见 <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Zen 文档（简体）</a>。</p><blockquote><p>Zen <strong>不是</strong>纯永久免费平台：多数旗舰模型按量付费，常需绑定账单 / 充值；下方「免费模型」适合在额度内试用。政策以官网为准。</p></blockquote><h2 id="官网与入口" tabindex="-1">官网与入口 <a class="header-anchor" href="#官网与入口" aria-label="Permalink to &quot;官网与入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>地址</th></tr></thead><tbody><tr><td>Zen 介绍</td><td><a href="https://opencode.ai/en/zen" target="_blank" rel="noreferrer">opencode.ai/zen</a></td></tr><tr><td>登录 / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>文档（简体）</td><td><a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">opencode.ai/docs/zh-cn/zen</a></td></tr><tr><td>模型元数据</td><td><code>https://opencode.ai/zen/v1/models</code></td></tr><tr><td>API Base URL（OpenAI 兼容）</td><td><code>https://opencode.ai/zen/v1</code></td></tr></tbody></table><h2 id="免费怎么获取" tabindex="-1">免费怎么获取 <a class="header-anchor" href="#免费怎么获取" aria-label="Permalink to &quot;免费怎么获取&quot;">​</a></h2><ol><li>打开 <a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a>（GitHub / Google）登录。</li><li>按控制台指引创建 <strong>API Key</strong>。官方流程常要求补充账单信息；若只想用免费档，仍建议先看清自动充值是否关闭，避免误扣费。</li><li>在 MiniTavern 选 <strong>自定义 (OpenAI)</strong>，Base URL 填 <code>https://opencode.ai/zen/v1</code>，模型填下方 <strong>Free</strong> ID。</li></ol><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>免费方式</td><td>若干模型定价为 <strong>Free</strong>（在 OpenCode 上限内）；用于收集反馈，可能随时调整或下线</td></tr><tr><td>付费方式</td><td>按量付费；余额低于 $5 时默认可自动充值 $20（可在控制台改或关）</td></tr><tr><td>绑卡</td><td>官方「工作原理」写明需添加账单信息；以控制台实际为准</td></tr><tr><td>隐私注意</td><td>免费档（如 Big Pickle、MiMo Free、Hy3、Nemotron Free、Muse Contributor Free）可能用日志改进模型；Nemotron 为 NVIDIA 试用端点，勿传机密</td></tr></tbody></table><p>完整价目与弃用表见 <a href="https://opencode.ai/docs/zh-cn/zen/#%E5%AE%9A%E4%BB%B7" target="_blank" rel="noreferrer">Zen · 定价</a>。</p><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>模型 ID <strong>大小写敏感</strong>。Zen 对不同厂商走不同路径：<code>/chat/completions</code>、<code>/responses</code>、<code>/messages</code> 或 Gemini 专用路径。MiniTavern <strong>自定义 (OpenAI)</strong> 走 Chat Completions，请优先选下表 <strong>OpenAI 兼容</strong> 行。</p><p>完整表见 <a href="https://opencode.ai/docs/zh-cn/zen/#%E7%AB%AF%E7%82%B9" target="_blank" rel="noreferrer">Zen · 端点</a>；也可用 <code>GET https://opencode.ai/zen/v1/models</code>。</p><h3 id="文本-·-免费档-推荐先试" tabindex="-1">文本 · 免费档（推荐先试） <a class="header-anchor" href="#文本-·-免费档-推荐先试" aria-label="Permalink to &quot;文本 · 免费档（推荐先试）&quot;">​</a></h3><p>均走 <code>…/v1/chat/completions</code>（除 Muse Contributor Free 走 Responses）。</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>mimo-v2.5-free</code></td><td>小米 MiMo V2.5 免费档</td></tr><tr><td><code>hy3-free</code></td><td>Hy3 Free</td></tr><tr><td><code>big-pickle</code></td><td>隐身模型，免费档</td></tr><tr><td><code>nemotron-3-ultra-free</code></td><td>NVIDIA Nemotron 试用，勿传机密</td></tr><tr><td><code>nemotron-3.5-lightning-free</code></td><td>同上</td></tr><tr><td><code>muse-spark-1.2-contributor-free</code></td><td>贡献者免费档；走 <code>/responses</code>，<strong>MiniTavern 测连可能不适用</strong>，且允许用提示词训练 Meta 模型</td></tr></tbody></table><h3 id="文本-·-付费但-openai-兼容-可选" tabindex="-1">文本 · 付费但 OpenAI 兼容（可选） <a class="header-anchor" href="#文本-·-付费但-openai-兼容-可选" aria-label="Permalink to &quot;文本 · 付费但 OpenAI 兼容（可选）&quot;">​</a></h3><p>适合已充值、仍想用同一 Base URL：</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code> / <code>deepseek-v4-pro</code></td><td>DeepSeek（有 Peak / Off-Peak 价差）</td></tr><tr><td><code>glm-5.1</code> / <code>glm-5.2</code> / <code>glm-5</code></td><td>智谱 GLM</td></tr><tr><td><code>kimi-k2.5</code> / <code>kimi-k2.6</code> / <code>kimi-k2.7-code</code> / <code>kimi-k3</code></td><td>Kimi</td></tr><tr><td><code>minimax-m2.5</code> / <code>minimax-m2.7</code> / <code>minimax-m3</code></td><td>MiniMax</td></tr></tbody></table><h3 id="其它协议-minitavern-慎用" tabindex="-1">其它协议（MiniTavern 慎用） <a class="header-anchor" href="#其它协议-minitavern-慎用" aria-label="Permalink to &quot;其它协议（MiniTavern 慎用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>示例 ID</th><th>端点类型</th></tr></thead><tbody><tr><td>GPT 系列</td><td><code>gpt-5.5</code>、<code>gpt-5.4-nano</code> 等</td><td><code>/zen/v1/responses</code></td></tr><tr><td>Claude 系列</td><td><code>claude-sonnet-4-6</code>、<code>claude-haiku-4-5</code> 等</td><td><code>/zen/v1/messages</code></td></tr><tr><td>Gemini 系列</td><td><code>gemini-3-flash</code> 等</td><td><code>/zen/v1/models/&lt;id&gt;</code></td></tr></tbody></table><p>上述与 MiniTavern 默认的 OpenAI Chat Completions <strong>不完全同一路径</strong>；角色扮演聊天请优先用免费档或上表 OpenAI 兼容模型。需要 Claude 时可改用 App 内 <strong>Claude(Anthropic)</strong> 官方 Key，或换 <a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a> 等统一 OpenAI 网关。</p><h3 id="图片-视频" tabindex="-1">图片 / 视频 <a class="header-anchor" href="#图片-视频" aria-label="Permalink to &quot;图片 / 视频&quot;">​</a></h3><p>Zen 文档当前目录以<strong>语言模型</strong>为主，<strong>无独立免费生图 / 视频档</strong>。生图请看 <a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a> 或 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费生图</a>。</p><h2 id="在-minitavern-里怎么填" tabindex="-1">在 MiniTavern 里怎么填 <a class="header-anchor" href="#在-minitavern-里怎么填" aria-label="Permalink to &quot;在 MiniTavern 里怎么填&quot;">​</a></h2><p>通用步骤见 <a href="/ultra_guides/manual/model-link">模型连接</a>。</p><p>路径：<strong>设置 → 模型 → 模型连接 → 新建</strong></p><ol><li>平台选 <strong>自定义 (OpenAI)</strong></li><li>Base URL：<code>https://opencode.ai/zen/v1</code></li><li>粘贴 API Key</li><li>模型 ID 填 <code>mimo-v2.5-free</code>（或其它 Free / chat 兼容 ID）</li><li><strong>测试</strong> → 成功后再设为默认</li></ol><blockquote><p>若测连失败：确认未选 GPT Responses / Claude Messages 专用 ID；关闭自动充值后再试免费档；对照 <a href="/ultra_guides/manual/errors">错误排错</a>。</p></blockquote><h2 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h2><ul><li><a href="/ultra_guides/free-cloud/">免费云端总览</a></li><li><a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a> — 一把 Key 试多款 <code>*-free</code> 闭源/开源模型 + 生图</li><li><a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/manual/model-link">模型连接</a></li></ul>',30)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
